import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS } from './customers.js';
import { getProduct } from './catalogue.js';
import { roundCents } from './money.js';
import { nextInvoiceNumber } from './numbering.js';

/**
 * Validate that issueDate is in YYYY-MM-DD format and is a real date.
 * @param {string} dateStr
 * @returns {boolean}
 */
function isValidDate(dateStr) {
  if (typeof dateStr !== 'string') return false;
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(dateStr);
  if (!m) return false;
  const [, year, month, day] = m;
  try {
    const d = new Date(`${year}-${month}-${day}T00:00:00Z`);
    return d.toISOString().startsWith(dateStr);
  } catch {
    return false;
  }
}

/**
 * Validate discount percent (0-100, can be decimal).
 * @param {unknown} discount
 * @returns {boolean}
 */
function isValidDiscountPercent(discount) {
  return typeof discount === 'number' && discount >= 0 && discount <= 100;
}

/**
 * Create an invoice from a customer id, issue date, and line items.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }> }} input
 * @returns {import('./result.js').Result<{ customerId: string, issueDate: string, status: 'draft', lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent?: number }> }>}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  const customerResult = getCustomer(customerId);
  if (!customerResult.ok) return customerResult;
  const customer = customerResult.value;

  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  if (!lines || lines.length === 0) return fail('NO_LINES');

  const invoiceLines = [];
  for (const line of lines) {
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    if (line.discountPercent !== undefined && !isValidDiscountPercent(line.discountPercent)) {
      return fail('DISCOUNT_INVALID');
    }

    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const { name, unitPrice, vatRate } = productResult.value;
    const newLine = {
      sku: line.sku,
      name,
      qty: line.qty,
      unitPrice,
      vatRate,
    };

    // If line has explicit discountPercent (even if 0), use it; otherwise use tier discount
    if (line.discountPercent !== undefined) {
      newLine.discountPercent = line.discountPercent;
    } else {
      const tierDiscount = TIER_DISCOUNTS[customer.tier];
      if (tierDiscount !== 0) {
        newLine.discountPercent = tierDiscount;
      }
    }

    invoiceLines.push(newLine);
  }

  return ok({
    customerId,
    issueDate,
    status: 'draft',
    lines: invoiceLines,
  });
}

/**
 * Calculate the total amount for a single line (qty × unitPrice).
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {import('./result.js').Result<number>}
 */
export function lineTotal(line) {
  if (!line || typeof line.qty !== 'number' || typeof line.unitPrice !== 'number') {
    return fail('LINE_INVALID');
  }
  return ok(roundCents(line.qty * line.unitPrice));
}

/**
 * Calculate the discount amount for a single line.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
 * @returns {import('./result.js').Result<number>}
 */
export function lineDiscount(line) {
  if (!line || typeof line.qty !== 'number' || typeof line.unitPrice !== 'number') {
    return fail('LINE_INVALID');
  }

  const discountPercent = line.discountPercent ?? 0;
  if (!isValidDiscountPercent(discountPercent)) {
    return fail('DISCOUNT_INVALID');
  }

  const totalResult = lineTotal(line);
  if (!totalResult.ok) return totalResult;

  const discount = roundCents((totalResult.value * discountPercent) / 100);
  return ok(Math.max(0, discount));
}

/**
 * Calculate the VAT amount for a single line.
 * VAT is calculated on the line total after discount.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }} line
 * @returns {import('./result.js').Result<number>}
 */
export function lineVat(line) {
  if (!line || typeof line.qty !== 'number' || typeof line.unitPrice !== 'number' || typeof line.vatRate !== 'number') {
    return fail('LINE_INVALID');
  }

  const totalResult = lineTotal(line);
  if (!totalResult.ok) return totalResult;

  const discountResult = lineDiscount(line);
  if (!discountResult.ok) return discountResult;

  const amountAfterDiscount = Math.max(0, totalResult.value - discountResult.value);
  const vat = roundCents((amountAfterDiscount * line.vatRate) / 100);
  return ok(Math.max(0, vat));
}

/**
 * Calculate totals for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }> }} invoice
 * @returns {import('./result.js').Result<{ subtotal: number, discount: number, vat: number, total: number }>}
 */
export function invoiceTotals(invoice) {
  if (!invoice || !Array.isArray(invoice.lines) || invoice.lines.length === 0) {
    return fail('INVOICE_INVALID');
  }

  let subtotal = 0;
  let discount = 0;
  let vat = 0;
  for (const line of invoice.lines) {
    const totalResult = lineTotal(line);
    if (!totalResult.ok) return totalResult;
    subtotal += totalResult.value;

    const discountResult = lineDiscount(line);
    if (!discountResult.ok) return discountResult;
    discount += discountResult.value;

    const vatResult = lineVat(line);
    if (!vatResult.ok) return vatResult;
    vat += vatResult.value;
  }

  subtotal = roundCents(subtotal);
  discount = roundCents(discount);
  vat = roundCents(vat);
  const total = roundCents(Math.max(0, subtotal - discount + vat));

  return ok({
    subtotal,
    discount,
    vat,
    total,
  });
}

/**
 * Add a line to an invoice, or increase qty if the SKU already exists.
 * @param {{ status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent?: number }> }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} input
 * @returns {import('./result.js').Result<{ status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent?: number }> }>}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  if (!invoice || invoice.status !== 'draft') return fail('NOT_DRAFT');

  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  if (discountPercent !== undefined && !isValidDiscountPercent(discountPercent)) {
    return fail('DISCOUNT_INVALID');
  }

  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const { name, unitPrice, vatRate } = productResult.value;

  const newLines = invoice.lines.map((line) => ({ ...line }));
  const existingIndex = newLines.findIndex((line) => line.sku === sku);

  if (existingIndex >= 0) {
    newLines[existingIndex].qty += qty;
  } else {
    const newLine = {
      sku,
      name,
      qty,
      unitPrice,
      vatRate,
    };
    if (discountPercent !== undefined) {
      newLine.discountPercent = discountPercent;
    }
    newLines.push(newLine);
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from an invoice by SKU.
 * @param {{ status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number }> }} invoice
 * @param {string} sku
 * @returns {import('./result.js').Result<{ status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number }> }>}
 */
export function removeLine(invoice, sku) {
  if (!invoice || invoice.status !== 'draft') return fail('NOT_DRAFT');

  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex < 0) return fail('LINE_NOT_FOUND');

  if (invoice.lines.length === 1) return fail('NO_LINES');

  const newLines = invoice.lines.filter((_, index) => index !== lineIndex);

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Issue an invoice, assigning it a number and changing status to 'issued'.
 * @param {{ status: string, issueDate: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number }> }} invoice
 * @param {Array<string>} existingNumbers
 * @returns {import('./result.js').Result<{ status: string, number: string, issueDate: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number }> }>}
 */
export function issueInvoice(invoice, existingNumbers) {
  if (!invoice || invoice.status !== 'draft') return fail('NOT_DRAFT');

  const numberResult = nextInvoiceNumber(existingNumbers, invoice.issueDate);
  if (!numberResult.ok) return numberResult;

  return ok({
    ...invoice,
    number: numberResult.value,
    status: 'issued',
  });
}

