import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { roundCents } from './money.js';
import { nextInvoiceNumber } from './numbering.js';

/**
 * Validate that issueDate is in YYYY-MM-DD format and is a real date.
 * @param {string} dateStr
 * @returns {boolean}
 */
function isValidDate(dateStr) {
  if (typeof dateStr !== 'string') return false;
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(dateStr);
  if (!m) return false;
  const [, year, month, day] = m;
  try {
    const d = new Date(`${year}-${month}-${day}T00:00:00Z`);
    return d.toISOString().startsWith(dateStr);
  } catch {
    return false;
  }
}

/**
 * Validate discount percent (0-100, can be decimal).
 * @param {unknown} discount
 * @returns {boolean}
 */
function isValidDiscountPercent(discount) {
  return typeof discount === 'number' && discount >= 0 && discount <= 100;
}

/**
 * Create an invoice from a customer id, issue date, and line items.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }> }} input
 * @returns {import('./result.js').Result<{ customerId: string, issueDate: string, status: 'draft', lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent?: number }> }>}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  const normalisedCustomerId = normalizeId(customerId);
  const customerResult = getCustomer(normalisedCustomerId);
  if (!customerResult.ok) return customerResult;
  const customer = customerResult.value;

  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  if (!lines || lines.length === 0) return fail('NO_LINES');

  const invoiceLines = [];
  for (const line of lines) {
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    if (line.discountPercent !== undefined && !isValidDiscountPercent(line.discountPercent)) {
      return fail('DISCOUNT_INVALID');
    }

    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const { name, unitPrice, vatRate } = productResult.value;
    const newLine = {
      sku: line.sku,
      name,
      qty: line.qty,
      unitPrice,
      vatRate,
    };

    // If line has explicit discountPercent (even if 0), use it; otherwise use tier discount
    if (line.discountPercent !== undefined) {
      newLine.discountPercent = line.discountPercent;
    } else {
      const tierDiscount = TIER_DISCOUNTS[customer.tier];
      if (tierDiscount !== 0) {
        newLine.discountPercent = tierDiscount;
      }
    }

    invoiceLines.push(newLine);
  }

  return ok({
    customerId,
    issueDate,
    status: 'draft',
    lines: invoiceLines,
  });
}

